function logoName(value){return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,' ').trim();}
function findTeamLogo(value,category){
 const name=logoName(value);if(!name)return null;
 const teams=category?TEAM_LOGOS[category]||[]:Object.values(TEAM_LOGOS).flat();
 const matches=teams.filter(team=>team.aliases.some(alias=>logoName(alias)===name));
 return matches.length===1?matches[0]:null;
}
function watchTeamLogo(w,event){
 const category=w.match?.category||event?.category;
 if(w.kind==='team')return findTeamLogo(w.match?.team_label,category)||findTeamLogo(w.match?.slug,category);
 if(w.kind!=='event'||!event||!category)return null;
 const slugs=String(event.slug||'').split('-at-'),teams=TEAM_LOGOS[category]||[];
 const named=teams.filter(team=>(' '+logoName(event.name)+' ').includes(' '+logoName(team.name)+' '));
 for(const slug of slugs){const team=findTeamLogo(slug,category);if(team&&!named.includes(team))named.push(team);}
 // A custom alert label may choose between teams confirmed by the event; it
 // never invents a team identity for an unrelated event.
 const preferred=named.filter(team=>team.aliases.some(alias=>logoName(alias).length>=4&&(' '+logoName(w.label)+' ').includes(' '+logoName(alias)+' ')));
 return preferred.length===1?preferred[0]:findTeamLogo(slugs.length===2?slugs[1]:'',category)||(named.length===1?named[0]:null);
}
function watchTeamStamp(w,event){
 const team=watchTeamLogo(w,event),fallback=icon(w.kind==='team'?'ball':'ticket');
 return team?`<span class="sport-stamp has-team-logo"><span class="logo-fallback">${fallback}</span><img class="team-logo" src="${esc(team.logo)}" alt="${esc(team.name)}" width="36" height="36" loading="lazy" decoding="async" referrerpolicy="no-referrer"></span>`:`<span class="sport-stamp">${fallback}</span>`;
}
